import {createPluginShowcase} from './plugins.js';
import {createShowcase} from './showcase.js';
import {createDeviceMorph} from './device-morph.js';
import {createEnhancements} from './enhancements.js';
import Lenis from './vendor/lenis.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],html=document.documentElement;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches||new URLSearchParams(location.search).has('motion-off');
if(reduced)html.classList.add('reduced-motion');
const gsap=window.gsap,ST=window.ScrollTrigger;gsap.registerPlugin(ST);
const cleanups=[],driver={p:0},pointer={x:0,y:0},aim={x:0,y:0};let experience=null,storyTrigger=null,lenis=null,paused=false,chapter=-1,mode='web',visible=true;
function clamp(a,b,x){return Math.min(b,Math.max(a,x))}function smooth(a,b,x){let t=clamp(0,1,(x-a)/(b-a));return t*t*(3-2*t)}function mix(a,b,t){return a+(b-a)*t}
const menu=$('#menu-dialog');$('.menu-button').addEventListener('click',()=>{menu.showModal();lenis?.stop()});$('.menu-close').addEventListener('click',()=>menu.close());menu.addEventListener('close',()=>{lenis?.start();$('.menu-button').focus()});
function scrollToTarget(target,instant=false){if(lenis){lenis.resize();lenis.scrollTo(target,{immediate:instant,offset:typeof target==='string'?-85:0,duration:1.1,easing:t=>1-Math.pow(1-t,4)});}else if(typeof target==='number')scrollTo({top:target,behavior:instant||reduced?'instant':'smooth'});else $(target)?.scrollIntoView({behavior:instant||reduced?'instant':'smooth'})}
function seekStory(value,instant=false){scrollToTarget(storyTrigger.start+value/7*(storyTrigger.end-storyTrigger.start),instant);if(instant){ST.update();storyTrigger.getTween()?.progress(1);driver.p=value;applyStory(0)}}
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a||a.hasAttribute('data-jump'))return;let target=a.getAttribute('href');if(menu.open)menu.close();if(target==='#'){e.preventDefault();scrollToTarget(0);history.replaceState(null,'',location.pathname+location.search)}else if($(target)){e.preventDefault();scrollToTarget(target);history.replaceState(null,'',target)}});
$$('[data-jump]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();if(menu.open)menu.close();const n=+b.dataset.jump;$('.story').dataset.requestedChapter=n;if(storyTrigger)seekStory(n===5?7:n,e.detail===0);else scrollToTarget('#chapter-'+n,true)}));
$('.motion-toggle').addEventListener('click',()=>{paused=!paused;$('.motion-toggle').setAttribute('aria-pressed',paused);$('.motion-toggle').setAttribute('aria-label',paused?'Resume ambient animation':'Pause ambient animation');$('.motion-toggle>span').textContent=paused?'▶':'Ⅱ';$('.motion-toggle small').textContent=paused?'Resume motion':'Pause motion'});
const deviceMorph=createDeviceMorph({gsap,reduced});cleanups.push(()=>deviceMorph.dispose());
const modes={web:{copy:'A browser tab is all it takes. Orbit, zoom, and explore without an app or a plug-in.',note:'No installs. No downloads. Just a link.'},ar:{copy:'Place a scene in the world around you. Let your audience experience a product in their own space.',note:'Augmented reality on compatible devices.'},xr:{copy:'Step inside the scene. Turn a shared link into a sense of presence on a supported XR headset.',note:'Extended reality on compatible headsets.'}};
function setMode(name,focus=false){mode=name;$('.device-frame').dataset.mode=name;$$('.reality-tabs [data-mode]').forEach(b=>{const active=b.dataset.mode===name;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1;if(active&&focus)b.focus()});$('#reality-description').textContent=modes[name].copy;$('#mode-description').textContent=modes[name].note;$('#mode-description').setAttribute('aria-labelledby','mode-'+name);$('.device-status').textContent={web:'WEB 3D · BROWSER',ar:'AR · PHONE',xr:'XR · HEADSET'}[name]}
function selectMode(name,focus=false,instant=false){const value=['web','ar','xr'].indexOf(name);if(storyTrigger){seekStory(4+value,instant);if(focus)$('#mode-'+name).focus()}else{setMode(name,focus);deviceMorph.to(value,instant||reduced)}}
const tabButtons=$$('.reality-tabs [data-mode]');tabButtons.forEach((b,i)=>{b.addEventListener('click',event=>selectMode(b.dataset.mode,false,event.detail===0));b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;selectMode(tabButtons[n].dataset.mode,true,true)}})});
function staticStory(){html.classList.remove('story-ready');html.classList.add('static-story','no-gl');document.documentElement.style.setProperty('--stage-ink','#1d1d1f');document.documentElement.style.setProperty('--stage-muted','#59616e');}
const desktopPoses=[{x:.74,y:.46,scale:1,rx:.12,ry:-.45,rz:-.16,explode:0,solid:1,wire:0,spread:0,particles:0,shadow:.8,dark:0},{x:.71,y:.48,scale:1.04,rx:.17,ry:.32,rz:.12,explode:.16,solid:.08,wire:1,spread:.08,particles:.25,shadow:0,dark:1},{x:.72,y:.52,scale:.83,rx:-.1,ry:.1,rz:-.18,explode:1,solid:.10,wire:.60,spread:1,particles:1.5,shadow:0,dark:0},{x:.74,y:.49,scale:.29,rx:.18,ry:Math.PI*2-.4,rz:.14,explode:0,solid:1,wire:.05,spread:0,particles:.1,shadow:0,dark:0},{x:.72,y:.51,scale:.78,rx:.06,ry:Math.PI*2-.24,rz:-.04,explode:0,solid:1,wire:0,spread:0,particles:0,shadow:0,dark:1},{x:.26,y:.49,scale:.89,rx:-.18,ry:Math.PI*2+1.04,rz:.14,explode:0,solid:1,wire:0,spread:0,particles:0,shadow:.55,dark:0}];
const backgrounds=['#ffffff','#0066cc','#ffffff','#edf3ff','#0066cc','#ffffff'];
const bgMix=backgrounds.slice(0,-1).map((c,i)=>gsap.utils.interpolate(c,backgrounds[i+1]));
const darkMix=['#1d1d1f','#ffffff','#1d1d1f','#1d1d1f','#ffffff','#1d1d1f'];const inkMix=darkMix.slice(0,-1).map((c,i)=>gsap.utils.interpolate(c,darkMix[i+1]));const muted=['#59616e','#ffffff','#59616e','#59616e','#ffffff','#59616e'];const mutedMix=muted.slice(0,-1).map((c,i)=>gsap.utils.interpolate(c,muted[i+1]));
function applyStory(t){const raw=clamp(0,7,driver.p),p=raw<=4?raw:raw<=6?4:raw-2;$('.story').dataset.progress=p.toFixed(3);$('.story').dataset.scrollProgress=raw.toFixed(3);const phase=clamp(0,2,raw-4),view=phase<1?smooth(.25,.75,phase):1+smooth(1.25,1.75,phase);if(raw>3.5&&raw<6.5){const next=['web','ar','xr'][Math.round(view)];if(next!==mode)setMode(next);deviceMorph.render(view);}const i=Math.min(4,Math.floor(p)),f=smooth(.12,.88,p-i),mobile=innerWidth<600,pose={};for(const key of Object.keys(desktopPoses[0]))pose[key]=mix(desktopPoses[i][key],desktopPoses[i+1][key],f);if(mobile){const my=[.66,.66,.69,.69,.69,.69],mx=[.56,.56,.56,.5,.54,.48],ss=[1,.97,.83,.40,.72,.94];pose.x=mix(mx[i],mx[i+1],f);pose.y=mix(my[i],my[i+1],f);pose.scale=mix(ss[i],ss[i+1],f)}if(Math.abs(p-4)<.35){const target=mode==='ar'?.12:mode==='xr'?-.72:0;pose.ry+=target;pose.scale*=mode==='ar'?.8:1}
 if(new URLSearchParams(location.search).has('poster')){pose.x=.5;pose.y=.47;pose.scale=1.1;pose.ry=-.5;pose.rx=.22;pose.rz=-.1;pose.progress=1.15;experience?.update(pose,0,{x:0,y:0},true);return}
 pose.progress=p;if(raw>3.5&&raw<6.5){pose.view=view;pose.focus=smooth(3.5,3.95,raw)*(1-smooth(6.05,6.5,raw));} const ink=inkMix[i](f);html.style.setProperty('--stage-ink',ink);html.style.setProperty('--stage-muted',mutedMix[i](f));html.style.setProperty('--stage-line',pose.dark>.5?'#d6e4ff35':'#1d1d1f23');$('.stage-wash').style.background=bgMix[i](f);$('.stage-grid').style.opacity=pose.dark*.5;
 const scaleNames=['01 / OBJECT','02 / OBJECT + TABLE','03 / FURNISHED INTERIOR','04 / APARTMENT BUILDING','05 / NEIGHBOURHOOD','06 / THE COMPLETE SCENE'];const scaleNode=$('#scene-scale');if(scaleNode)scaleNode.textContent=scaleNames[Math.round(p)];const n=clamp(0,5,Math.round(p));if(n!==chapter){chapter=n;$('#current-chapter').textContent=String(n).padStart(2,'0');$$('.chapter-nav button').forEach((b,j)=>{b.classList.toggle('selected',j===n);if(j===n)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')})}
 $$('.story-panel').forEach((panel,j)=>{const dist=Math.abs(p-j),alpha=1-smooth(.25,.55,dist);panel.style.opacity=alpha;panel.style.visibility=alpha>.015?'visible':'hidden';panel.style.transform='translate3d(0,'+((j-p)*64)+'px,0)';panel.inert=alpha<.5;panel.setAttribute('aria-hidden',alpha<.5)});
 $('.rail-progress>i').style.transform='scaleX('+raw/7+')';$('.ghost-type').style.opacity=1-smooth(0,.8,p);$('.ghost-type').style.transform='translate3d('+(-p*15)+'%,0,0)';$$('.orbit').forEach(el=>el.style.opacity=1-smooth(0,.9,p));$('.geometry-number').style.opacity=(1-smooth(.25,.8,Math.abs(p-1)))*.7;$('.geometry-number').style.transform='translate3d('+((p-1)*8)+'%,0,0)';$('.stream-line').style.opacity=1-smooth(.2,.85,Math.abs(p-2));$('.link-capsule').style.opacity=1-smooth(.2,.6,Math.abs(p-3));$('.device-frame').style.opacity=1-smooth(.25,.7,Math.abs(p-4));experience?.update(pose,t,pointer,paused);}
const plugins=createPluginShowcase({gsap,reduced});cleanups.push(()=>plugins.dispose());
const showcase=createShowcase({gsap,ST,reduced});cleanups.push(()=>showcase.dispose());
const enhancements=createEnhancements({gsap,ST,reduced,scrollToTarget});cleanups.push(()=>enhancements.dispose());
function onPage(){const ctx=gsap.context(()=>{
 html.classList.add('story-ready');gsap.set('.story-panel',{autoAlpha:0});gsap.set('.hero-panel',{autoAlpha:1});
 gsap.from('.hero-panel .panel-copy',{y:26,opacity:0,duration:1.1,ease:'expo.out',clearProps:'opacity,transform'});
 const tween=gsap.to(driver,{p:7,ease:'none',scrollTrigger:{trigger:'.story-stage',start:'top top',end:()=>'+='+innerHeight*(innerWidth<600?7.4:8),pin:true,scrub:.7,invalidateOnRefresh:true,onToggle:s=>{$('.site-header').classList.toggle('on-story',s.isActive||scrollY<10)}}});storyTrigger=tween.scrollTrigger;
 enhancements.mount();showcase.mount();
 ST.create({start:10,onUpdate:()=>$('.site-header').classList.toggle('scrolled',scrollY>80)});
 });return()=>ctx.revert()}
async function init(){if(reduced||!gsap){staticStory();return}try{const mod=await import('./model.js');experience=await mod.createExperience($('#stage-three'));html.classList.remove('static-story','no-gl');html.classList.add('gl-ready');}catch(e){console.warn('3D preview unavailable; using the static story.',e);staticStory();return}
 if(innerWidth>800){lenis=new Lenis({lerp:.1,wheelMultiplier:1,anchors:false});lenis.on('scroll',ST.update);const lenisTick=t=>lenis.raf(t*1000);gsap.ticker.add(lenisTick);cleanups.push(()=>{gsap.ticker.remove(lenisTick);lenis.destroy()});gsap.ticker.lagSmoothing(0)}
 if(new URLSearchParams(location.search).has('poster')){html.classList.add('poster-capture');const posterTick=()=>applyStory(0);gsap.ticker.add(posterTick);cleanups.push(()=>gsap.ticker.remove(posterTick));applyStory(0);return}cleanups.push(onPage());const move=e=>{aim.x=e.clientX/innerWidth-.5;aim.y=e.clientY/innerHeight-.5};if(matchMedia('(pointer:fine)').matches){addEventListener('pointermove',move,{passive:true});cleanups.push(()=>removeEventListener('pointermove',move))}
 const observer=new IntersectionObserver(e=>visible=e[0].isIntersecting);observer.observe($('.story-stage'));cleanups.push(()=>observer.disconnect());const tick=t=>{if(!visible||document.hidden)return;const k=1-Math.pow(.93,gsap.ticker.deltaRatio());pointer.x+=(aim.x-pointer.x)*k;pointer.y+=(aim.y-pointer.y)*k;applyStory(t)};gsap.ticker.add(tick);cleanups.push(()=>gsap.ticker.remove(tick));applyStory(0);document.fonts.ready.then(()=>{ST.refresh();lenis?.resize();if(location.hash&&$(location.hash)&&!location.hash.startsWith('#chapter'))scrollToTarget(location.hash,true)});
 }
init().catch(()=>staticStory());addEventListener('pagehide',()=>{cleanups.forEach(fn=>fn());experience?.dispose()});
